FUNCTION_BLOCK FB_P14
VAR_INPUT
    ipText : STRING(254);
END_VAR
VAR_OUTPUT
    ipValue : UDINT := UDINT#0;
END_VAR
VAR
    firstScan : BOOL := TRUE;
    textLength : INT;
    position : INT;
    character : STRING(1);
    digitIndex : INT;
    segmentCount : INT := 1;
    segmentValue : UDINT := UDINT#0;
    assembledValue : UDINT := UDINT#0;
    hasDigit : BOOL := FALSE;
    valid : BOOL;
END_VAR

(*
    待审语义冲突：
    纯组合解析要求每拍输出当前输入的解析值，但 C10 要求上电当拍
    输出 0；当首拍输入为合法非零地址时，两者不能同时满足。
    本实现保留显式 C10：首拍输出 0，从第二拍起逐拍完整解析。
    未经编译 profile 或逐周期测试验证。

    不施加 15 字符长度限制：K1/K2 未禁止前导零，
    因此按 STRING(254) 中实际内容逐字符校验。
*)

ipValue := UDINT#0;

IF firstScan THEN
    firstScan := FALSE;
    segmentCount := 1;
    segmentValue := UDINT#0;
    assembledValue := UDINT#0;
    hasDigit := FALSE;
ELSE
    textLength := LEN(ipText);
    segmentCount := 1;
    segmentValue := UDINT#0;
    assembledValue := UDINT#0;
    hasDigit := FALSE;
    valid := textLength > 0;

    FOR position := 1 TO textLength DO
        IF valid THEN
            character := MID(ipText, 1, position);

            IF character = '.' THEN
                IF (NOT hasDigit) OR (segmentCount >= 4) THEN
                    valid := FALSE;
                ELSE
                    assembledValue :=
                        assembledValue * UDINT#256 + segmentValue;
                    segmentCount := segmentCount + 1;
                    segmentValue := UDINT#0;
                    hasDigit := FALSE;
                END_IF;
            ELSE
                digitIndex := FIND('0123456789', character);

                IF digitIndex = 0 THEN
                    valid := FALSE;
                ELSE
                    (* segmentValue 在此前始终不超过 255，
                       此处最大中间值为 2559，不会发生 UDINT 溢出。 *)
                    segmentValue :=
                        segmentValue * UDINT#10
                        + INT_TO_UDINT(digitIndex - 1);
                    hasDigit := TRUE;

                    IF segmentValue > UDINT#255 THEN
                        valid := FALSE;
                    END_IF;
                END_IF;
            END_IF;
        END_IF;
    END_FOR;

    IF valid AND hasDigit AND (segmentCount = 4) THEN
        (* 此前仅组装三个字节，最后一步最大结果为 16#FFFFFFFF。 *)
        ipValue := assembledValue * UDINT#256 + segmentValue;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
